WITH base AS (SELECT *, unit_price * quantity AS line_total FROM order_items WHERE product_id IS NOT NULL AND product_id IS NOT NULL), enriched AS (SELECT *, ROUND(unit_price / SUM(unit_price) OVER (PARTITION BY product_id), 4) AS unit_price_share, ROUND(unit_price / SUM(unit_price) OVER (PARTITION BY order_id), 4) AS unit_price_share_2, SUM(line_total) OVER (ORDER BY line_total, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_line_total, ROW_NUMBER() OVER (ORDER BY quantity DESC, id) AS row_seq, AVG(line_total) OVER (PARTITION BY order_id, product_id ORDER BY unit_price, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS line_total_avg_6_prior FROM base), valid AS (SELECT *, GREATEST(unit_price_share, line_total) AS greatest_unit_price_share_line_total FROM enriched WHERE row_seq != 7), joined AS (SELECT a.*, p.stock_qty, p.cost FROM valid a LEFT JOIN products p ON a.product_id = p.id WHERE p.stock_qty BETWEEN 172 AND 254), latest AS (SELECT id, order_id, product_id, quantity, line_total, unit_price_share, row_seq, line_total_avg_6_prior, stock_qty, cost FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY line_total_avg_6_prior DESC NULLS FIRST, id) AS row_num FROM joined) t WHERE row_num = 1) SELECT CASE WHEN quantity >= 9 THEN 'LARGE' ELSE 'SMALL' END AS quantity_tier, CASE WHEN cost >= 690 THEN 'HIGH' ELSE 'LOW' END AS cost_tier, COUNT(DISTINCT order_id) AS distinct_order_ids, COUNT(DISTINCT order_id) AS distinct_order_ids_2, BIT_OR(quantity) AS quantity_bit_or FROM latest GROUP BY CASE WHEN quantity >= 9 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN cost >= 690 THEN 'HIGH' ELSE 'LOW' END ORDER BY cost_tier NULLS LAST;
